        let mut slices = access_errors
            .iter()
            .map(|diagnostic| &source[diagnostic.span.lo as usize..diagnostic.span.hi as usize])
            .collect::<Vec<_>>();
        slices.sort_unstable();
        assert_eq!(slices, ["-counter", "current++"]);
